import json
import re
from datetime import datetime, timezone
import streamlit as st

st.set_page_config(page_title="Cynbit Lead Intelligence Copilot", page_icon="🎯", layout="wide")

st.title("🎯 Cynbit Lead Intelligence Copilot")
st.caption("Proof of concept • Explainable lead triage • Synthetic sample data only")
st.info(
    "This demo explores a potential opportunity aligned with Cynbit's public focus on AI automation and CRM workflows. "
    "Scores are generated by transparent baseline rules—not a trained ML model—and should not be used for real business decisions."
)

EXAMPLES = {
    "High-intent AI project": "We are a growing ecommerce company looking for an AI chatbot and CRM automation to handle customer questions. Our budget is around $30,000 and we would like to start within 3 weeks. Please arrange a discovery call.",
    "Medium-priority CRM integration": "We want to connect our CRM with email marketing and automate some repetitive follow-up tasks. Budget is approximately $10,000. We are comparing options for next quarter.",
    "Low-urgency website request": "We have a minor website button issue. It is not urgent and can be looked at whenever someone is available. We have a small budget.",
    "Custom inquiry": ""
}

def score_lead(text: str):
    """Explainable heuristic baseline. Not trained machine learning."""
    t = text.lower()
    score = 20
    reasons = ["Starting baseline score (+20)"]

    budget_terms = ["budget", "$", "₹", "inr", "usd", " lakh", " lakhs", "k"]
    if any(term in t for term in budget_terms):
        score += 15
        reasons.append("Budget or commercial context is mentioned (+15)")

    urgency_terms = ["urgent", "asap", "immediately", "within", "this week", "deadline", "soon", "3 weeks", "next month"]
    if any(term in t for term in urgency_terms):
        score += 15
        reasons.append("A timeline or urgency signal is present (+15)")

    fit_terms = ["ai", "automation", "crm", "chatbot", "machine learning", "agent", "integration", "data"]
    matched_fit = sorted({term for term in fit_terms if term in t})
    if matched_fit:
        score += 20
        reasons.append("Inquiry mentions service-aligned terms: " + ", ".join(matched_fit) + " (+20)")

    outcome_terms = ["increase", "reduce", "customer questions", "save time", "leads", "conversion", "repetitive", "handle"]
    matched_outcome = [term for term in outcome_terms if term in t]
    if matched_outcome:
        score += 15
        reasons.append("A business need or desired outcome is described (+15)")

    if len(re.findall(r"\w+", text)) >= 25:
        score += 10
        reasons.append("Inquiry includes useful detail (25+ words) (+10)")

    low_intent_terms = ["not urgent", "whenever", "no rush", "just curious", "minor issue", "small budget"]
    matched_low = [term for term in low_intent_terms if term in t]
    if matched_low:
        score -= 15
        reasons.append("Low-urgency or limited-scope wording detected: " + ", ".join(matched_low) + " (-15)")

    score = max(0, min(100, score))
    priority = "High" if score >= 70 else "Medium" if score >= 45 else "Low"
    action = {
        "High": "Prioritize for human review and offer a discovery call.",
        "Medium": "Ask one or two clarifying questions and schedule a follow-up.",
        "Low": "Send a helpful response and place in a low-priority follow-up queue."
    }[priority]
    followup = {
        "High": "Hi, thanks for sharing your project requirements. This looks like something worth discussing in more detail. Could we arrange a short discovery call to understand your goals, timeline, and success criteria?",
        "Medium": "Hi, thanks for contacting us. We'd be happy to understand your requirements better. Could you share your preferred timeline and the main outcome you would like to achieve?",
        "Low": "Hi, thanks for reaching out. We've received your request and would be happy to learn more. When convenient, please share any additional context or timing preferences so we can suggest the next step."
    }[priority]
    return {
        "score": score,
        "priority": priority,
        "reasons": reasons,
        "recommended_action": action,
        "follow_up_draft": followup,
        "model_type": "Explainable rule-based baseline (not trained ML)",
        "created_at_utc": datetime.now(timezone.utc).isoformat()
    }

left, right = st.columns([1.15, 0.85], gap="large")
with left:
    st.subheader("1. Enter an inquiry")
    example = st.selectbox("Load a synthetic example", list(EXAMPLES.keys()))
    default_text = EXAMPLES[example]
    inquiry = st.text_area("Customer inquiry", value=default_text, height=190,
                           placeholder="Paste a project inquiry here…")
    evaluate = st.button("Evaluate inquiry", type="primary", use_container_width=True)

with right:
    st.subheader("2. What this prototype does")
    st.markdown("""
    - Extracts simple signals from the inquiry text
    - Calculates a transparent 0–100 priority score
    - Shows the reasons behind the result
    - Suggests a next action and a draft reply
    - Exports the result as JSON
    """)
    st.caption("Use synthetic examples only. Do not enter confidential customer information.")

if evaluate:
    if not inquiry.strip():
        st.warning("Enter an inquiry or choose one of the examples first.")
    else:
        result = score_lead(inquiry.strip())
        st.session_state["last_result"] = {"inquiry": inquiry.strip(), **result}

if "last_result" in st.session_state:
    result = st.session_state["last_result"]
    st.divider()
    st.subheader("Lead assessment")
    c1, c2, c3 = st.columns(3)
    c1.metric("Priority score", f'{result["score"]}/100')
    c2.metric("Priority tier", result["priority"])
    c3.metric("Approach", "Explainable baseline")
    st.progress(result["score"] / 100)
    out_left, out_right = st.columns(2, gap="large")
    with out_left:
        st.markdown("#### Why this score?")
        for reason in result["reasons"]:
            st.write("• " + reason)
        st.markdown("#### Recommended next action")
        st.success(result["recommended_action"])
    with out_right:
        st.markdown("#### Suggested follow-up draft")
        st.text_area("Draft message", value=result["follow_up_draft"], height=180, key="followup_display")
    payload = json.dumps(result, indent=2, ensure_ascii=False)
    st.download_button("Download assessment as JSON", data=payload,
                       file_name="lead_assessment.json", mime="application/json")
    st.caption("Important: score is a demo heuristic, not a probability of conversion. Validate thresholds against labeled outcomes before real use.")

with st.expander("Technical notes & limitations"):
    st.markdown("""
    **Current pipeline:** inquiry text → keyword/length signals → weighted rules → score and tier → reasons and suggested action.

    **Why no trained model?** This assessment prototype has no verified, labeled historical lead dataset. A transparent baseline is more defensible than claiming a model was trained without data.

    **Next iteration:** collect consented, appropriately governed historical inquiries with outcomes; compare this baseline against logistic regression and tree-based models; evaluate precision, recall, F1 and PR-AUC for qualified leads; calibrate thresholds with the business team; monitor drift and human override rates.

    **LLM extension:** optionally use a constrained prompt to extract structured fields and draft a response, with schema validation, privacy controls, and human review. The current version does not call an LLM or send data to an external API.
    """)
